# ═══════════════════════════════════════════════════════════════
# 六、将以上知识注册到 RAG 引擎
# ═══════════════════════════════════════════════════════════════

def get_all_deep_chunks():
    """Return all deep knowledge as RAG-indexable chunks."""
    chunks = []

    # 滴天髓十干
    for gan, info in DITIAN_SUI_SHIGAN.items():
        text = f"【滴天髓·{gan}干论】\n原文：{info['原文']}\n任铁樵注：{info['任氏注要']}\n喜忌：{info['喜忌']}\n取用要领：{info['取用要领']}\n性格：{info['性格']}"
        chunks.append({"source": f"ditian_sui.{gan}干", "content": text})

    # 子平真诠格局
    for ge, info in ZIPING_GEJV_DEEP.items():
        parts = [f"【子平真诠·{ge}详解】\n定义：{info.get('定义','')}"]
        if info.get("成格"):
            parts.append("成格条件：" + "；".join(info["成格"]))
        if info.get("破格"):
            parts.append("破格条件：" + "；".join(info["破格"]))
        if info.get("太过"):
            parts.append(f"太过：{info['太过']}")
        if info.get("不及"):
            parts.append(f"不及：{info['不及']}")
        if info.get("行运"):
            parts.append(f"行运：{info['行运']}")
        if info.get("古籍"):
            parts.append(f"典据：{info['古籍']}")
        chunks.append({"source": f"ziping_zhenchuan.{ge}", "content": "\n".join(parts)})

    # 穷通宝鉴
    for gan, months in QIONGTONG_FULL.items():
        for zhi, text in months.items():
            chunks.append({"source": f"qiongtong.{gan}干{zhi}月", "content": f"【穷通宝鉴·{gan}日干{zhi}月】{text}"})

    # 增删卜易
    for section, content in ZENGSHAN_BUYI.items():
        if isinstance(content, dict):
            for k, v in content.items():
                if isinstance(v, list):
                    chunks.append({"source": f"zengshan_buyi.{section}.{k}", "content": f"【增删卜易·{section}·{k}】\n" + "\n".join(v)})
                else:
                    chunks.append({"source": f"zengshan_buyi.{section}.{k}", "content": f"【增删卜易·{section}·{k}】{v}"})
        elif isinstance(content, list):
            chunks.append({"source": f"zengshan_buyi.{section}", "content": f"【增删卜易·{section}】\n" + "\n".join(content)})

    # 紫微主星
    for star, info in ZIWEI_ZHUXING.items():
        parts = [f"【紫微斗数·{star}星详论】"]
        parts.append(f"五行：{info.get('五行','')}")
        parts.append(f"特质：{info.get('特质','')}")
        if info.get("庙旺"):
            parts.append(f"庙旺：{info['庙旺']}")
        if info.get("落陷"):
            parts.append(f"落陷：{info['落陷']}")
        if info.get("四化"):
            parts.append(f"四化：{info['四化']}")
        parts.append(f"断语：{info.get('断语','')}")
        if info.get("格局"):
            parts.append("格局：" + "；".join(info["格局"]))
        chunks.append({"source": f"ziwei_zhuxing.{star}", "content": "\n".join(parts)})

    return chunks
